public final class MenuRBMKOutgasser extends RBMKMenu<BlockEntityRBMKOutgasser>{public MenuRBMKOutgasser(int i,Inventory p,BlockPos x){super(ModRBMKMenus.RBMK_OUTGASSER.get(),i,p,x,BlockEntityRBMKOutgasser.class,2);add();}public MenuRBMKOutgasser(int i,Inventory p,BlockEntityRBMKOutgasser b){super(ModRBMKMenus.RBMK_OUTGASSER.get(),i,p,b,2);add();}private void add(){addSlot(new Slot(container,BlockEntityRBMKOutgasser.SLOT_INPUT,48,45){@Override public boolean mayPlace(ItemStack s){return OutgasserRecipes.INSTANCE.getRecipe(s)!=null;}});addSlot(new Slot(container,BlockEntityRBMKOutgasser.SLOT_OUTPUT,112,69){@Override public boolean mayPlace(ItemStack s){return false;}});addPlayer();}@Override public ItemStack quickMoveStack(Player p,int i){return move(p,i,2,true);}}
